declare(strict_types=1);

/**
 * Adds to tests/fixtures/nextcloud-api/<major>.php the two surfaces the Deck assignment retry of issue #26 names:
 * OCP\Notification\IManager (defer/flush) and OCA\Deck\Notification\NotificationHelper (markCardAssignedAsRead).
 * Every other class of the fixture is left as it is.
 *
 * Usage: php tests/fixtures/nextcloud-api/generate-assignment-notices.php <major> <tree>
 *
 * <tree> holds lib/public/Notification of the nextcloud/server release and apps/deck/lib/Notification of the
 * nextcloud/deck release named in NextcloudApiUsage::SOURCES for that major, fetched file by file from the official
 * tags, e.g. https://raw.githubusercontent.com/nextcloud/server/v35.0.0/lib/public/Notification/ and
 * https://raw.githubusercontent.com/nextcloud/deck/v1.19.0/lib/Notification/NotificationHelper.php. The parent
 * interfaces of IManager live in the same directory, so the inherited members are part of its surface.
 */

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\NextcloudApiUsage;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

require __DIR__ . '/../../../vendor/autoload.php';

[, $major, $tree] = $argv + [null, null, null];
$pins = NextcloudApiUsage::SOURCES[$major] ?? null;
$files = [
	'OCP\\Notification\\IManager' => ['lib/public/Notification/IManager.php', 'nextcloud/server v' . ($pins['server'] ?? '')],
	'OCA\\Deck\\Notification\\NotificationHelper' => ['apps/deck/lib/Notification/NotificationHelper.php', 'nextcloud/deck v' . ($pins['deck'] ?? '')],
];
if ($pins === null || $tree === null) {
	fwrite(STDERR, "usage: php generate-assignment-notices.php <major of NextcloudApiUsage::SOURCES> <tree>\n");
	exit(2);
}
$parser = new SourceParser($tree);
$path = __DIR__ . '/' . $major . '.php';
$fixture = require $path;
$notes = [];
foreach ($files as $class => [$file, $release]) {
	$surface = is_file($tree . '/' . $file) ? $parser->surface($class) : null;
	if ($surface === null) {
		throw new RuntimeException('The tree lacks ' . $class);
	}
	$fixture['classes'][$class] = $surface;
	$notes[] = $class . ' from ' . $release . ' (sha256 ' . hash_file('sha256', $tree . '/' . $file) . ')';
}
foreach (['defer', 'flush'] as $method) {
	if (!isset($fixture['classes']['OCP\\Notification\\IManager']['methods'][$method])) {
		throw new RuntimeException('IManager lacks ' . $method . '()');
	}
}
if (!isset($fixture['classes']['OCA\\Deck\\Notification\\NotificationHelper']['methods']['markCardAssignedAsRead'])) {
	throw new RuntimeException('NotificationHelper lacks markCardAssignedAsRead()');
}
ksort($fixture['classes']);
$original = file_get_contents($path);
$header = substr($original, 0, strpos($original, 'return ['));
$header = preg_replace('~// (Notification manager surface|Assignment notice surfaces) generated[^\n]*\n~', '', $header);
$header .= '// Assignment notice surfaces generated by generate-assignment-notices.php: ' . implode('; ', $notes) . ".\n";
FixtureFile::write($path, $header, $fixture);
echo 'Added the assignment notice surfaces to NC' . $major . "\n";
